<template>
  <div class="page"><el-card shadow="never"><div class="toolbar"><el-button type="primary" @click="openCreate">新增用户</el-button><el-input v-model="keyword" placeholder="用户名 / 姓名" clearable style="width:220px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows" border stripe><el-table-column prop="username" label="用户名" width="150"/><el-table-column prop="realName" label="姓名" width="150"/><el-table-column label="角色" min-width="200"><template #default="{row}"><el-tag v-for="id in row.roleIds" :key="id" size="small" class="tag">{{ roleName(id) }}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-switch :model-value="row.isActive===1" @change="(v:boolean|string|number)=>toggle(row,!!v)"/></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="warning" @click="password(row)">重置密码</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, sizes, prev, pager, next" @change="load"/></div></el-card><el-dialog v-model="visible" :title="form.id?'编辑用户':'新增用户'" width="500px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item label="姓名" prop="realName"><el-input v-model="form.realName"/></el-form-item><el-form-item v-if="!form.id" label="初始密码" prop="password"><el-input v-model="form.password" show-password/></el-form-item><el-form-item label="角色"><el-select v-model="form.roleIds" multiple style="width:100%"><el-option v-for="x in roles" :key="x.role.id" :label="x.role.name" :value="x.role.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div>
</template>
<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import type {FormInstance,FormRules} from 'element-plus';import {systemApi} from '@/api/system';import type {SystemUser,RoleView} from '@/api/system'
const loading=ref(false),keyword=ref(''),page=ref(1),size=ref(10),total=ref(0),rows=ref<SystemUser[]>([]),roles=ref<RoleView[]>([]),visible=ref(false),formRef=ref<FormInstance>();const form=reactive<any>({});const rules:FormRules={username:[{required:true,message:'请输入用户名'}],realName:[{required:true,message:'请输入姓名'}],password:[{required:true,message:'请输入密码'}]};const roleName=(id:number)=>roles.value.find(x=>x.role.id===id)?.role.name||'未知';
async function load(){loading.value=true;try{const r=await systemApi.users({page:page.value,size:size.value,keyword:keyword.value||undefined});rows.value=r.records;total.value=r.total}catch{}finally{loading.value=false}}async function init(){roles.value=await systemApi.roles();await load()}function openCreate(){Object.assign(form,{id:undefined,username:'',realName:'',password:'',roleIds:[]});visible.value=true}function edit(r:SystemUser){Object.assign(form,{...r,password:''});visible.value=true}async function save(){if(!await formRef.value?.validate().catch(()=>false))return;try{if(form.id)await systemApi.updateUser(form.id,{realName:form.realName,active:form.isActive??1,roleIds:form.roleIds});else await systemApi.createUser({username:form.username,realName:form.realName,password:form.password,active:1,roleIds:form.roleIds});ElMessage.success('保存成功');visible.value=false;await load()}catch{}}async function toggle(r:SystemUser,active:boolean){try{await systemApi.updateUser(r.id,{realName:r.realName,active:active?1:0,roleIds:r.roleIds});await load()}catch{}}async function password(r:SystemUser){const p=prompt('请输入新密码');if(!p)return;try{await systemApi.resetPassword(r.id,p);ElMessage.success('密码已重置')}catch{}}onMounted(init)
</script><style scoped>.toolbar{display:flex;gap:12px;margin-bottom:16px}.tag{margin-right:6px}.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
